export const dreamsInMotionId = (number: StoryLessonNumber) => `conversational-skills-L4-C4-${number}-${dreamsInMotionEpisodes[number].skill}-ja-v1`;
export function buildDreamsInMotionLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildNewBeginningLesson(number, previous, 'https://api.fluentxverse.com', reference, {
    episode: dreamsInMotionEpisodes[number], id: dreamsInMotionId(number), chapterName: 'Dreams in Motion',
    setting: 'Kamo House cafe and a fictional tea shop in Uji; an Osaka gallery and design agency. Seoul appears as a possible future presentation opportunity, not booked travel.',
    previousSummary: index === 0 ? 'The second market succeeded. Claire committed to monthly events, with the next date to confirm. Emma and Ren are dating; Leo and Nao are dating. Emma and Leo exchanged peaceful good wishes. A Fukuoka visit remained an unbooked idea.' : dreamsInMotionEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: 'Level 4 Chapter 4 adapts the user\'s Dreams in Motion outline. Eight episodes belong in story slots1-4/6-9; Lessons5/10 remain dynamic checkpoints. Keep speaking/listening/reading/speaking then speaking/speaking/reading/speaking. The existing monthly event expands into Kamo Collective, not a first-ever market. Maintain professional and romantic continuity without physical-intimacy scenes. No images; Japanese support, direct roles, short tutor-first dialogue, concise private listening, fresh reading evidence, standard guides, keyed exercises and fixed feedback. Future Level 4 Chapter 5 awaits the user\'s outline.',
  });
  lesson.storyData.characters = [
    { id: 'emma', name: 'Emma', role: 'main', description: 'Designer creating Kamo Collective\'s visual identity. Dates Ren and works comfortably with old friends; later joins a proposed Seoul presentation team.' },
    { id: 'ren', name: 'Ren', role: 'supporting', description: 'Designer preparing promotional materials. Contributes practical ideas and humour and builds a genuine working friendship with Leo.' },
    { id: 'leo', name: 'Leo', role: 'supporting', description: 'Kyoto baker taking measured steps toward his own brand, testing matcha pastries and considering limited evening kitchen rental rather than opening a shop immediately.' },
    { id: 'nao', name: 'Nao', role: 'supporting', description: 'Ceramic artist balancing an Osaka gallery opportunity with Kamo Collective; dates Leo and helps coordinate artists and practical solutions.' },
    { id: 'claire', name: 'Claire', role: 'supporting', description: 'Cafe organiser developing a creative community space. Manages budget and scheduling, learns to delegate and coordinates a rain-day fallback.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 4, chapter: 4, lessonNumber: number, levelBadge: 'BEGINNER', chapterLabel: 'Chapter 4: Dreams in Motion', status: previous?.status || 'draft', overlayColor: '#17252bcc', supportLanguage: 'ja' };
}
export function buildDreamsInMotionChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildDreamsInMotionLesson(number, {}, reference));
}
